import { useState } from "react";
import { Mail, Lock, Eye, EyeOff } from 'lucide-react';
import StudentDashboard from "../StudentDashboard";
import MentorDashboard from "../MentorDashboard";
import PlacementDashboard from "../PlacementDashboard";

const ProfessionalLogin = () => {
  const [selectedUserType, setSelectedUserType] = useState('');
  const [showLogin, setShowLogin] = useState(false);
  const [showPassword, setShowPassword] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [loginData, setLoginData] = useState({ email: '', password: '' });
  const [loginError, setLoginError] = useState('');
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [authenticatedUser, setAuthenticatedUser] = useState(null);

  const VALID_CREDENTIALS = {
    'student': { email: 'student@college.edu', password: 'student123' },
    'mentor': { email: 'mentor@college.edu', password: 'mentor123' },
    'placement-cell': { email: 'placement@college.edu', password: 'placement123' }
  };

  const userTypes = [
    { id: 'student', title: 'Student', description: 'Access your placement dashboard' },
    { id: 'mentor', title: 'Mentor', description: 'Guide and review student applications' },
    { id: 'placement-cell', title: 'Placement Cell', description: 'Manage campus recruitment' }
  ];

  const handleLogin = async (e) => {
    e.preventDefault();
    setLoginError('');
    setIsLoading(true);

    const creds = VALID_CREDENTIALS[selectedUserType];

    setTimeout(() => {
      if (loginData.email === creds.email && loginData.password === creds.password) {
        setIsAuthenticated(true);
        setAuthenticatedUser({
          email: loginData.email,
          userType: selectedUserType,
          name: selectedUserType.charAt(0).toUpperCase() + selectedUserType.slice(1)
        });
      } else {
        setLoginError('Invalid email or password');
      }
      setIsLoading(false);
    }, 600);
  };

  const handleLogout = () => {
    setIsAuthenticated(false);
    setAuthenticatedUser(null);
    setSelectedUserType('');
    setShowLogin(false);
    setLoginData({ email: '', password: '' });
    setLoginError('');
  };

  if (isAuthenticated && authenticatedUser) {
    if (authenticatedUser.userType === 'student') {
      return <StudentDashboard onLogout={handleLogout} />;
    } else if (authenticatedUser.userType === 'mentor') {
      return <MentorDashboard onLogout={handleLogout} />;
    } else if (authenticatedUser.userType === 'placement-cell') {
      return <PlacementDashboard onLogout={handleLogout} />;
    }
  }

  if (showLogin && selectedUserType) {
    const currentUserType = userTypes.find(ut => ut.id === selectedUserType);
    const credentials = VALID_CREDENTIALS[selectedUserType];

    return (
      <div className="min-h-screen bg-white flex items-center justify-center p-4">
        <div className="w-full max-w-md">
          <div className="border border-gray-200 rounded p-8">
            <button
              onClick={() => {
                setShowLogin(false);
                setSelectedUserType('');
                setLoginData({ email: '', password: '' });
                setLoginError('');
              }}
              className="mb-8 text-sm text-gray-500 hover:text-gray-900"
            >
              ← Back
            </button>

            <div className="mb-8">
              <h1 className="text-2xl font-medium text-gray-900 mb-1">
                Sign in
              </h1>
              <p className="text-sm text-gray-500">
                {currentUserType.title}
              </p>
            </div>

            <form onSubmit={handleLogin} className="space-y-4">
              <div>
                <label className="block text-sm text-gray-700 mb-1">
                  Email
                </label>
                <input
                  type="email"
                  required
                  value={loginData.email}
                  onChange={(e) => setLoginData({ ...loginData, email: e.target.value })}
                  className="w-full px-3 py-2 border border-gray-300 rounded text-sm focus:outline-none focus:border-gray-900"
                  placeholder="you@college.edu"
                />
              </div>

              <div>
                <label className="block text-sm text-gray-700 mb-1">
                  Password
                </label>
                <div className="relative">
                  <input
                    type={showPassword ? "text" : "password"}
                    required
                    value={loginData.password}
                    onChange={(e) => setLoginData({ ...loginData, password: e.target.value })}
                    className="w-full px-3 py-2 border border-gray-300 rounded text-sm focus:outline-none focus:border-gray-900"
                    placeholder="Enter password"
                  />
                  <button
                    type="button"
                    onClick={() => setShowPassword(!showPassword)}
                    className="absolute right-3 top-1/2 transform -translate-y-1/2 text-gray-400 hover:text-gray-600"
                  >
                    {showPassword ? <EyeOff className="h-4 w-4" /> : <Eye className="h-4 w-4" />}
                  </button>
                </div>
              </div>

              {loginError && (
                <div className="p-3 bg-gray-50 border border-gray-200 rounded">
                  <p className="text-sm text-gray-700">{loginError}</p>
                </div>
              )}

              <div className="p-3 bg-gray-50 rounded">
                <p className="text-xs text-gray-500 mb-1">Demo</p>
                <p className="text-xs text-gray-700">{credentials.email} / {credentials.password}</p>
              </div>

              <button
                type="submit"
                disabled={isLoading}
                className="w-full bg-gray-900 hover:bg-gray-800 text-white text-sm font-medium py-2.5 rounded disabled:opacity-50"
              >
                {isLoading ? 'Signing in...' : 'Sign in'}
              </button>
            </form>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-white">
      {/* Header */}
      <header className="border-b border-gray-200">
        <div className="max-w-5xl mx-auto px-6 py-4">
          <h1 className="text-base font-medium text-gray-900">CampusConnect</h1>
        </div>
      </header>

      {/* Main */}
      <main className="max-w-3xl mx-auto px-6 py-20">
        <div className="text-center mb-16">
          <h2 className="text-3xl font-medium text-gray-900 mb-3">
            Campus Placement System
          </h2>
          <p className="text-gray-600">
            Select your role to continue
          </p>
        </div>

        {/* User Selection */}
        <div className="grid md:grid-cols-3 gap-4">
          {userTypes.map((userType) => (
            <button
              key={userType.id}
              onClick={() => {
                setSelectedUserType(userType.id);
                setShowLogin(true);
              }}
              className="border border-gray-200 rounded p-6 text-left hover:border-gray-900 transition-colors"
            >
              <h3 className="text-base font-medium text-gray-900 mb-2">
                {userType.title}
              </h3>
              <p className="text-sm text-gray-600">
                {userType.description}
              </p>
            </button>
          ))}
        </div>
      </main>

      {/* Footer */}
      <footer className="border-t border-gray-200 mt-24">
        <div className="max-w-5xl mx-auto px-6 py-6">
          <p className="text-sm text-gray-500 text-center">
            © 2025 CampusConnect
          </p>
        </div>
      </footer>
    </div>
  );
};

export default ProfessionalLogin;
